using Challenge;using System.Security.Cryptography;using System.Text;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}var key="secret"u8.ToArray();string Sig(byte[] x)=>Convert.ToHexString(HMACSHA256.HashData(key,x)).ToLowerInvariant();var q=(char)34;var raw=Encoding.UTF8.GetBytes($"{{ {q}id{q} : {q}a{q} }}");C("C01",()=>new Receiver(key,new()).Handle(raw,Sig(raw)));C("C02",()=>!new Receiver(key,new()).Handle(raw,new string('0',64)));C("C03",()=>{var d=new WebhookStore();var s=new Receiver(key,d);s.Handle(raw,Sig(raw));s.Handle(raw,Sig(raw));return d.Effects.Count==1;});C("C04",()=>{var x="no-json"u8.ToArray();return !new Receiver(key,new()).Handle(x,Sig(x));});C("C05",()=>true);
